import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const AdminListCurso = () => {
  const [cursos, setCursos] = useState([
    "Contabilidade II",
    "Programação I",
    "Economia I",
    "Inglês II",
    "Francês I",
    "Gestão I",
  ]);

  const [novoCurso, setNovoCurso] = useState("");

  const adicionarCurso = () => {
    if (novoCurso.trim()) {
      setCursos([...cursos, novoCurso]);
      setNovoCurso("");
    }
  };

  const removerCurso = (index) => {
    setCursos(cursos.filter((_, i) => i !== index));
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="mt-3">
        <h3>Cursos</h3>
        <div className="d-flex mb-3">
          <input
            type="text"
            className="form-control me-2"
            placeholder="busque curso pelo nome"
            value={novoCurso}
            onChange={(e) => setNovoCurso(e.target.value)}
          />
          <button className="btn btn-primary" onClick={adicionarCurso}>
            Adicionar
          </button>
        </div>

        <ul className="list-group">
          {cursos.map((curso, index) => (
            <li
              key={index}
              className="list-group-item d-flex justify-content-between align-items-center"
            >
              {curso}
              <div>
                <button className="btn btn-outline-primary btn-sm mx-2">
                  ✏️
                </button>
                <button
                  className="btn btn-outline-danger btn-sm"
                  onClick={() => removerCurso(index)}
                >
                  🗑️
                </button>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default AdminListCurso;
